ruleExplore.bookList:
@js:
var query = /[?&]reader_query=([^&]*)/.exec(String(baseUrl));
var key = query ? decodeURIComponent(query[1].replace(/\+/g, " ")) : "";
key = String(java.t2s(key)).trim();
var links = java.getElements("a[href~=/book/[0-9]+$]");
var books = []; var seen = {};
for (var i = 0; i < links.size(); i++) {
  var item = links.get(i);
  // Image links can contain malformed attribute residue. Use the real visible
  // title link, including homepage headings, result-table titles and rankings.
  if (item.select("img").size() !== 0) continue;
  var name = String(item.text()).trim();
  var url = String(item.attr("href"));
  if (name !== "" && !seen[url] && (key === "" || String(java.t2s(name)).indexOf(key) >= 0)) {
    var card = item.closest("dl,li,tr");
    var cardLinks = card.select("a[href~=/book/[0-9]+$]");
    var oneBook = true;
    for (var j = 0; j < cardLinks.size(); j++) {
      if (String(cardLinks.get(j).attr("href")) !== url) oneBook = false;
    }
    books.push({name:name, bookUrl:url,
      author:oneBook ? String(card.select("a[href~=/people/[0-9]+$]").first().text()).trim() : "",
      coverUrl:oneBook && card.select("h3").size() !== 0 ? String(card.select("img").first().attr("src")) : "",
      kind:oneBook ? String(card.select(".flex a[href~=/all/]").first().text()).trim() : ""});
    seen[url] = true;
  }
}
books;
